SallaProductOptions.style = sallaProductOptionsCss;

function setBaseCurrencyHeader() {
    axios.defaults.headers.common.currency = salla?.config?.get?.('user.currency_code');
}

var http = {
    request(method, url, data, successCb = null, errorCb = null) {
        setBaseCurrencyHeader();
        return axios
            .request({url, data, method: method.toLowerCase(), responseType: 'json'})
            .then(successCb)
            .catch(errorCb);
    },

    get(url, successCb = null, errorCb = null, data) {
        // return this.request('get', url, data, successCb, errorCb);
        setBaseCurrencyHeader();
        return axios
            .get(url, {params: data})
            .then(successCb)
            .catch(errorCb);
    },

    post(url, data, successCb = null, errorCb = null) {
        return this.request('post', url, data, successCb, errorCb);
    },

    put(url, data, successCb = null, errorCb = null) {
        return this.request('put', url, data, successCb, errorCb);
    },

    delete(url, data, successCb = null, errorCb = null) {
        return this.request('delete', url, data, successCb, errorCb);
    },

    requestWithSupportAjax(url, payload, method = 'post') {
        return new Promise((resolve, reject) => {
            if (!window?.isLegacyTheme) {
                return this.request(method, url, payload, ({data}) => {
                    return resolve(data);
                }, ({response}) => {
                    return reject(response);
                })
            }

            /**
             * @deprecated to support legacy themes
             */
            setBaseCurrencyHeader();
            $.ajax({
                url: url,
                method: method.toUpperCase(),
                data: payload,
                headers: { currency: axios.defaults.headers.common.currency },
                async: false,
                success: function ({data}) {
                    return resolve(data);
                },
                error: function ({response}) {
                    return reject(response);
                }
            });
        })
    }
};

var DetectOS = {
  options: [],
  header:
    typeof navigator !== "undefined" && typeof window !== "undefined"
      ? [
          navigator.platform,
          navigator.userAgent,
          navigator.appVersion,
          navigator.vendor,
          window.opera,
        ]
      : [],
  dataos: [
    { name: "Windows Phone", value: "Windows Phone", version: "OS" },
    { name: "Windows", value: "Win", version: "NT" },
    { name: "iPhone", value: "iPhone", version: "OS" },
    { name: "iPad", value: "iPad", version: "OS" },
    { name: "Kindle", value: "Silk", version: "Silk" },
    { name: "Android", value: "Android", version: "Android" },
    { name: "PlayBook", value: "PlayBook", version: "OS" },
    { name: "BlackBerry", value: "BlackBerry", version: "/" },
    { name: "Macintosh", value: "Mac", version: "OS X" },
    { name: "Linux", value: "Linux", version: "rv" },
    { name: "Palm", value: "Palm", version: "PalmOS" },
  ],
  databrowser: [
    { name: "Chrome", value: "Chrome", version: "Chrome" },
    { name: "Firefox", value: "Firefox", version: "Firefox" },
    { name: "Safari", value: "Safari", version: "Version" },
    { name: "Internet Explorer", value: "MSIE", version: "MSIE" },
    { name: "Opera", value: "Opera", version: "Opera" },
    { name: "BlackBerry", value: "CLDC", version: "CLDC" },
    { name: "Mozilla", value: "Mozilla", version: "Mozilla" },
  ],
  init: function () {
    var agent = this.header.join(" "),
      os = this.matchItem(agent, this.dataos),
      browser = this.matchItem(agent, this.databrowser);

    return { os: os, browser: browser };
  },
  matchItem: function (string, data) {
    var i = 0,
      j = 0,
      regex,
      regexv,
      match,
      matches,
      version;

    for (i = 0; i < data.length; i += 1) {
      regex = new RegExp(data[i].value, "i");
      match = regex.test(string);
      if (match) {
        regexv = new RegExp(data[i].version + "[- /:;]([\\d._]+)", "i");
        matches = string.match(regexv);
        version = "";
        if (matches) {
          if (matches[1]) {
            matches = matches[1];
          }
        }
        if (matches) {
          matches = matches.split(/[._]+/);
          for (j = 0; j < matches.length; j += 1) {
            if (j === 0) {
              version += matches[j] + ".";
            } else {
              version += matches[j];
            }
          }
        } else {
          version = "0";
        }
        return {
          name: data[i].name,
          version: parseFloat(version),
        };
      }
    }
    return { name: "unknown", version: 0 };
  },
};

/**
 * @typedef {Object} ApplePayPaymentContact
 * @property {string} phoneNumber
 * @property {string} emailAddress
 * @property {string} givenName
 * @property {string} familyName
 * @property {string} [phoneticGivenName]
 * @property {string} [phoneticFamilyName]
 * @property {string[]} addressLines
 * @property {string} [subLocality]
 * @property {string} locality
 * @property {string} postalCode
 * @property {string} [subAdministrativeArea]
 * @property {string} administrativeArea
 * @property {string} country
 * @property {string} countryCode
 */


/**
 *
 * @param {SallaApplePay} SallaApplePay
 * @param {boolean} isAuthorized
 * @param {ApplePayPaymentContact} shippingContact
 *
 */
async function mutateShippingContact(SallaApplePay, shippingContact, isAuthorized = false) {
  salla.logger.log('🍏 Pay: mutateShippingContact called', shippingContact, isAuthorized);

  if (!SallaApplePay.detail.requiredShippingContactFields || SallaApplePay.detail.requiredShippingContactFields.length == 0) {
    return;
  }

  if (isAuthorized) {
    if (isGuestCheckout()) {

      if (
        !shippingContact.emailAddress ||
        !shippingContact.givenName ||
        !shippingContact.familyName ||
        !shippingContact.phoneNumber
      ) {
  
        salla.logger.warn('🍏 Pay: Guest contact fields are required', shippingContact);
  
        const errors = [];
        if (!shippingContact.emailAddress) {
          errors.push(new window.ApplePayError('shippingContactInvalid', 'emailAddress', 'Email address is required'));
        }

        if (!shippingContact.phoneNumber) {
          errors.push(new window.ApplePayError('shippingContactInvalid', 'phoneNumber', 'Phone number is required'));
        }

        if (!shippingContact.givenName || !shippingContact.familyName) {
          errors.push(new window.ApplePayError('shippingContactInvalid', 'name', 'Name is required'));
        }

        SallaApplePay.session.completePayment({
          status: SallaApplePay.session.STATUS_INVALID_SHIPPING_CONTACT,
          errors: errors
        });

        return;
      }

      await updateGuestContact(SallaApplePay, shippingContact);

    }

    // if authorized and not guest checkout, do nothing address already added
    return;
  }

  if (!SallaApplePay.detail.requiredShippingContactFields.includes('postalAddress')) {
    return;
  }

  return http.post(
    SallaApplePay.detail.shippingContactSelected.url.replace('{id}', SallaApplePay.id),
    {
      'country': shippingContact.country,
      'city': shippingContact.locality,
      'local': shippingContact.subLocality || shippingContact.administrativeArea || shippingContact.locality,
      'description': shippingContact.subAdministrativeArea,
      'street': shippingContact.addressLines?.join(", ") || shippingContact.administrativeArea,
      'country_code': shippingContact.countryCode,
      'postal_code': shippingContact.postalCode,
    },
    async ({ data }) => {
      if (typeof SallaApplePay.detail.shippingContactSelected.onSuccess === 'function') {
        SallaApplePay.detail.shippingContactSelected.onSuccess(data);
      }

      SallaApplePay.address_id = data.data.address_id;
      SallaApplePay.shipping_methods = data.data.shipping_methods;

      if (!SallaApplePay.shipping_methods || (SallaApplePay.shipping_methods && !SallaApplePay.shipping_methods.length)) {
        salla.logger.warn('🍏 Pay: We dont found any supported methods', data);

        SallaApplePay.session.completeShippingContactSelection({
          status: SallaApplePay.session.STATUS_INVALID_SHIPPING_POSTAL_ADDRESS,
          errors: [
            new window.ApplePayError('addressUnserviceable')
          ]
        });

        return
      }

      try {
        await SallaApplePay.selectApplePayShippingMethod(SallaApplePay.shipping_methods[0]);
      } catch (error) {
        salla.logger.warn('Failed set the shipping details to api', error);

        SallaApplePay.session.completeShippingContactSelection({
          status: SallaApplePay.session.STATUS_INVALID_SHIPPING_POSTAL_ADDRESS,
          errors: [
            new window.ApplePayError('addressUnserviceable')
          ]
        });

        return;
      }

      try {
        await SallaApplePay.recalculateTotal();
      } catch (error) {
        salla.logger.warn('🍏 Pay: Failed recalculate total', error);

        SallaApplePay.session.completeShippingContactSelection({
          status: SallaApplePay.session.STATUS_INVALID_SHIPPING_POSTAL_ADDRESS,
          errors: [
            new window.ApplePayError('addressUnserviceable')
          ]
        });

        return;
      }

      const updatedShippingContactSelection = {
        newTotal: SallaApplePay.prepareTotal(),
        newLineItems: SallaApplePay.prepareLineItems(),
        newShippingMethods: SallaApplePay.mappingShippingMethods(SallaApplePay.shipping_methods)
      };

      salla.logger.log('🍏 Pay: completeShippingContactSelection', updatedShippingContactSelection);

      SallaApplePay.session.completeShippingContactSelection(updatedShippingContactSelection);
    },
    ({ response }) => {
      salla.logger.warn('🍏 Pay: Failed add address via api', response);

      if (typeof SallaApplePay.detail.shippingContactSelected.onFailed === 'function') {
        SallaApplePay.detail.shippingContactSelected.onFailed(response);
      }

      // parse 422 errors
      let fields = response?.data?.error?.fields;

      let errors = getApplePayErrors({
        countryCode: fields?.country_code && fields.country_code.length > 0 ? fields.country_code[0] : null,
        locality: fields?.city && fields.city.length > 0 ? fields.city[0] : null,
        country: fields?.country && fields.country.length > 0 ? fields.country[0] : null,
      });

      if (errors.length === 0 && response?.data?.error?.message) {
        errors.push(new window.ApplePayError('shippingContactInvalid', 'locality', response?.data?.error?.message));
      }

      SallaApplePay.session.completeShippingContactSelection({
        newTotal: SallaApplePay.prepareTotal(),
        newLineItems: SallaApplePay.prepareLineItems(),
        status: SallaApplePay.session.STATUS_INVALID_SHIPPING_POSTAL_ADDRESS,
        errors: errors
      });
    }
  );
}

function isGuestCheckout() {
  return salla.config.isGuest() && salla.config.get('store.features').includes('guest-checkout');
}

/**
 * Update guest contact
 *
 * @param {SallaApplePay} SallaApplePay
 * @param {ApplePayPaymentContact} shippingContact
 *
 */
async function updateGuestContact(SallaApplePay, shippingContact) {
  salla.logger.log('🍏 Pay: Updating guest contact', shippingContact);

  return new Promise((resolve, reject) => {
    http.post(
      SallaApplePay.detail.guestContactSelected.url.replace('{id}', SallaApplePay.id),
      {
        'email': shippingContact.emailAddress || null,
        'first_name': shippingContact.givenName || null,
        'last_name': shippingContact.familyName || null,
        'phone_number': shippingContact.phoneNumber || null,
        'country_code': shippingContact.countryCode || null,
      },
      async ({ data }) => {
        if (typeof SallaApplePay.detail.guestContactSelected?.onSuccess === 'function') {
          SallaApplePay.detail.guestContactSelected.onSuccess(data);
        }
        resolve(data);
      },
      ({ response }) => {
        salla.logger.warn('🍏 Pay: Failed to update guest contact via api', response);

        if (typeof SallaApplePay.detail.guestContactSelected?.onFailed === 'function') {
          SallaApplePay.detail.guestContactSelected.onFailed(response);
        }

        // Reject the promise so it can be caught in onPaymentAuthorized
        reject({ response });
      }
    );
  });
}

function getApplePayErrors(fields) {
  return Object.entries(fields)
    .filter(([field, messages]) => messages && messages.length > 0)
    .map(([field, messages]) => new window.ApplePayError('shippingContactInvalid', field, messages[0]));
}

// SSR-safe: only access window in browser environment
if (typeof window !== 'undefined') {
  window.Salla = window.Salla || {};
  window.Salla.Payments = window.Salla.Payments || {};
}

// Apple Pay method identifier for the W3C Payment Request API.
const APPLE_PAY_METHOD = 'https://apple.com/apple-pay';

// Captured at module load, before the Apple Pay SDK is injected: real Safari /
// Apple devices expose `ApplePaySession` natively, whereas non-Safari browsers
// only get it once the SDK loads. Keeps native-vs-PaymentRequest routing stable.
const HAS_NATIVE_APPLE_PAY = typeof window !== 'undefined' && !!window.ApplePaySession;

/**
 * Full Example
 *
 * Salla.event.createAndDispatch('payments::apple-pay.start-transaction', {
 *                  amount: 1000,
 *                  validateMerchant: {
 *                      url: '{{ route('cp.marketplace.cart.pay', ['cart' => $cart]) }}',
 *                      // onFailed: (response) => {
 *                      //     laravel.ajax.errorHandler(response);
 *                      //     this.onCancel({}, response.data.error.message);
 *                      // },
 *                      // onSuccess: (response) => {
 *                      //     laravel.ajax.successHandler(response);
 *                      // }
 *                  },
 *                  authorized: {
 *                      url: '{{ route('cp.marketplace.cart.confirm', ['cart' => $cart]) }}',
 *                      // onFailed: (response) => {
 *                      //     laravel.ajax.errorHandler(response);
 *                      //     this.onCancel({}, response.data.error.message);
 *                      // },
 *                      // onSuccess: (response) => {
 *                      //     // nothing
 *                      // }
 *                  },
 *                  // onError: function (message) {
 *                  //     laravel.alert(message);
 *                  // }
 *              });
 */

// SSR-safe: define SallaApplePay as a stub during SSR, actual object in browser
const SallaApplePay = typeof window !== 'undefined' ? {
    session: null,
    detail: null,
    address_id: null,
    shipping_methods: [],
    total: undefined,
    request: undefined,
    id: undefined,
    countryCode: null,
    totals: [],
    shippingCompany: null,
    // Set true once onCancel has fired for the current transaction, so the
    // QR (PaymentRequest) dismissal catch can notify on a plain sheet-close
    // without double-firing when a prior handler (e.g. merchant validation)
    // already routed through onCancel. Reset at the start of each transaction.
    canceled: false,
    init: function () {
        document.removeEventListener('payments::apple-pay.start-transaction', SallaApplePay.startSession);
        Salla.event.addEventListener('payments::apple-pay.start-transaction', SallaApplePay.startSession);
    },

    initDefault: function () {
        if (!SallaApplePay.detail.onError) {
            SallaApplePay.detail.onError = function (message) {
                salla.notify.error(message);
            };
        }

        if (!SallaApplePay.detail.authorized.onFailed) {
            SallaApplePay.detail.authorized.onFailed = (response) => {
                salla.logger.log(JSON.stringify(response));
                salla.api.handleErrorResponse(response);
                SallaApplePay.onCancel({}, response.data.error.message);
            };
        }

        if (!SallaApplePay.detail.validateMerchant.onFailed) {
            SallaApplePay.detail.validateMerchant.onFailed = (response) => {
                salla.logger.log(JSON.stringify(response));
                salla.api.handleErrorResponse({response});
                SallaApplePay.onCancel({}, response.data.error.message);
            };
        }

        if (!SallaApplePay.detail.authorized.onSuccess) {
            SallaApplePay.detail.authorized.onSuccess = (response) => {
                salla.logger.log(JSON.stringify(response));
                salla.api.handleAfterResponseActions(response);
            };
        }
    },

    prepareLineItems: function () {
        if (!SallaApplePay.detail?.items?.length) {
            SallaApplePay.detail.items = [
                {
                    label: salla.lang.get('pages.cart.items_total'),
                    amount: parseFloat(SallaApplePay.detail.amount).toString()
                }
            ];
        }

        return SallaApplePay.detail.items;
    },

    prepareTotal: function () {
        return {
            // apple ask to use business name
            label: window.location.hostname || 'Salla',
            //label: salla.lang.get('pages.cart.final_total'),
            amount: parseFloat(SallaApplePay.detail.amount).toString()
        }
    },

    isPhysical() {
        return SallaApplePay.detail?.requiredShippingContactFields?.includes('postalAddress');
    },

    /**
     * Whether the native Apple Pay flow (Safari / Apple devices) can run. Gated
     * on the module-load capture so the SDK loading later can't flip a
     * non-Safari browser into the native path.
     */
    canUseNative: function () {
        if (!HAS_NATIVE_APPLE_PAY) {
            return false;
        }
        try {
            return ApplePaySession.canMakePayments();
        } catch (e) {
            return false;
        }
    },

    // Sourced from config (via the transaction detail). No fallback: a missing
    // identifier means Apple Pay isn't configured for this store, and callers
    // treat that null as the guard to skip Apple Pay.
    getMerchantIdentifier: function () {
        return (SallaApplePay.detail && SallaApplePay.detail.merchantIdentifier) || null;
    },

    startSession: async function (event) {

        SallaApplePay.detail = event.detail || event;

        // Fresh transaction → clear any cancel flag from a previous attempt.
        SallaApplePay.canceled = false;

        salla.log('🍏 Pay: payments::apple-pay.start-transaction', SallaApplePay.detail);

        SallaApplePay.initDefault();

        // Native (Safari / Apple devices) → classic ApplePaySession. Otherwise
        // (non-Safari / non-Apple device) → Payment Request API, which renders
        // Apple's "Scan Code with iPhone" QR sheet.
        if (!SallaApplePay.canUseNative()) {
            return SallaApplePay.startPaymentRequestSession(event);
        }

        return SallaApplePay.startNativeSession(event);
    },

    startNativeSession: async function (event) {

        let version = SallaApplePay.getApplePaySessionVersion();
        // Normalize to an array: the backend can serialize the networks list as a JSON object
        // (non-sequential PHP array keys). Copy it so we never mutate the shared `detail` reference.
        // Works for both legacy (plain array) and unified (object-shaped) payloads.
        let rawNetworks = SallaApplePay.detail.supportedNetworks;
        let supportedNetworks = Array.isArray(rawNetworks) ? [...rawNetworks] : Object.values(rawNetworks || {});
        if (!supportedNetworks.length) {
            supportedNetworks = ['masterCard', 'visa'];
        }
        if (version === 5 && !supportedNetworks.includes('mada')) {
            supportedNetworks.push('mada');
        }

        SallaApplePay.request = {
            countryCode: SallaApplePay.detail.countryCode || 'SA',
            supportsCouponCode: true,
            couponCode: '',
            currencyCode: SallaApplePay.detail.currency || 'SAR',
            requiredShippingContactFields: SallaApplePay.detail.requiredShippingContactFields ? SallaApplePay.detail.requiredShippingContactFields : [],
            merchantCapabilities: ['supports3DS'],
            supportedNetworks: supportedNetworks,
            supportedCountries: SallaApplePay.detail.supportedCountries || ['SA'],
            total: SallaApplePay.prepareTotal(),
            shippingContact: SallaApplePay.detail.shippingContact ? SallaApplePay.detail.shippingContact : {},
            shippingMethods: SallaApplePay.detail.shippingMethods && SallaApplePay.detail.shippingMethods.length ? SallaApplePay.mappingShippingMethods(event.detail.shippingMethods) : [],
            lineItems: SallaApplePay.prepareLineItems()
        };

        salla.log('🍏 Pay: init ', SallaApplePay.request);

        // https://developer.apple.com/documentation/apple_pay_on_the_web/applepaypaymentrequest
        SallaApplePay.session = new ApplePaySession(version, SallaApplePay.request);

        SallaApplePay.session.onshippingcontactselected = SallaApplePay.onShippingContactSelected;
        SallaApplePay.session.onshippingmethodselected = SallaApplePay.onShippingMethodSelected;
        SallaApplePay.session.onvalidatemerchant = SallaApplePay.onValidateMerchant;
        SallaApplePay.session.onpaymentauthorized = SallaApplePay.onPaymentAuthorized;
        SallaApplePay.session.oncancel = SallaApplePay.onCancel;
        SallaApplePay.session.oncouponcodechanged = SallaApplePay.onCouponCodeChanged;
        SallaApplePay.session.onpaymentmethodselected = SallaApplePay.onPaymentMethodSelected;

        // Hook between session creation and begin(). Return truthy to skip
        // begin() (caller handles it later, e.g. after async work).
        let skipBegin;
        if (typeof SallaApplePay.detail.onStartedSession === 'function') {
            skipBegin = SallaApplePay.detail.onStartedSession(SallaApplePay.session);
        }
        if (!skipBegin) {
            SallaApplePay.session.begin();
        }
    },
    onPaymentMethodSelected: async (event) => {
        salla.logger.log('🍏 Pay: onPaymentMethodSelected', event);

        // perform recalculate here only if digital product
        // if physical recalculate performed with shipping company
        if (!SallaApplePay.isPhysical()) {
            try {
                await SallaApplePay.recalculateTotal();
    
                const updatedPaymentDetails = {
                    newTotal: SallaApplePay.prepareTotal(),
                    newLineItems: SallaApplePay.prepareLineItems()
                };
    
                salla.logger.log('🍏 Pay: completePaymentMethodSelection', updatedPaymentDetails);

                SallaApplePay.session.completePaymentMethodSelection(updatedPaymentDetails);

            } catch (error) {
                salla.logger.warn('🍏 Pay: Failed recalculate total', error);
    
                SallaApplePay.session.completePaymentMethodSelection({
                    newTotal: SallaApplePay.prepareTotal(),
                    newLineItems: SallaApplePay.prepareLineItems(),
                    status: SallaApplePay.session.STATUS_FAILURE,
                    errors: [new window.ApplePayError("unknown", undefined, error?.response?.data?.error?.message || error?.response?.data?.error?.code || 'Failed to recalculate total')]
                });
            }
            return;
        }

        salla.logger.log('🍏 Pay: completePaymentMethodSelection', {
            newTotal: SallaApplePay.prepareTotal(),
            newLineItems: SallaApplePay.prepareLineItems(),
        });

        SallaApplePay.session.completePaymentMethodSelection({
            newTotal: SallaApplePay.prepareTotal(),
            newLineItems: SallaApplePay.prepareLineItems(),
        });
    },

    onCouponCodeChanged(event) {
        Salla.event.dispatch('payments::apple-pay.coupon.change', event);

        return http.post(SallaApplePay.detail.onCouponCodeChanged.url.replace('{id}', SallaApplePay.id), {
            'coupon': event.couponCode,
            'payment_method': 'apple_pay',
        }, async ({ data }) => {
            if (typeof SallaApplePay.detail.onCouponCodeChanged.onSuccess === 'function') {
                SallaApplePay.detail.onCouponCodeChanged.onSuccess(data);
            }

            salla.log('🍏 Pay: Coupon applied success');

            await SallaApplePay.recalculateTotal();

            SallaApplePay.session.completeCouponCodeChange({
                newTotal: SallaApplePay.prepareTotal(),
                newLineItems: SallaApplePay.prepareLineItems()
            });
        }, async (error) => {
            let response = error?.response;

            Salla.event.dispatch('payments::apple-pay.coupon.failed', response);

            // SallaApplePay.abortSession();
            if (typeof SallaApplePay.detail.onCouponCodeChanged.onFailed === 'function') {
                SallaApplePay.detail.onCouponCodeChanged.onFailed(response);
            }

            await SallaApplePay.recalculateTotal();

            SallaApplePay.session.completeCouponCodeChange({
                newTotal: SallaApplePay.prepareTotal(),
                newLineItems: SallaApplePay.prepareLineItems(),
                errors: [new window.ApplePayError('couponCodeInvalid')]
            });
        });
    },

    onCancel: (event = {}, message = null) => {
        SallaApplePay.canceled = true;
        SallaApplePay.detail.onError(message || salla.lang.get('pages.checkout.payment_failed'));
        Salla.event.createAndDispatch('payments::apple-pay.canceled', event);
    },

    /**
     * Confirm payment after authorization.
     *
     * @param event
     */
    onPaymentAuthorized: async (event) => {
        salla.logger.log('🍏 Pay: onPaymentAuthorized', event.payment);

        // update guest details
        try {
            await mutateShippingContact(SallaApplePay, event.payment.shippingContact, true);
        } catch (error) {
            salla.logger.error('🍏 Pay: Failed to update guest contact details', error);
            
            const response = error?.response || error;
            
            // Parse backend errors for shipping contact fields
            const fields = response?.data?.error?.fields || {};
            const errors = [];
            
            // Map backend field errors to Apple Pay contact field errors
            if (fields?.email && fields.email.length > 0) {
                errors.push(new window.ApplePayError('shippingContactInvalid', 'emailAddress', fields.email[0]));
            }

            if (fields?.phone && fields.phone.length > 0) {
                errors.push(new window.ApplePayError('shippingContactInvalid', 'phoneNumber', fields.phone[0]));
            }

            if (fields?.first_name && fields.first_name.length > 0) {
                errors.push(new window.ApplePayError('shippingContactInvalid', 'name', fields.first_name[0]));
            } else if (fields?.last_name && fields.last_name.length > 0) {
                errors.push(new window.ApplePayError('shippingContactInvalid', 'name', fields.last_name[0]));
            }
            
            // If no specific field errors, use general error message
            if (errors.length === 0) {
                const errorMessage = response?.data?.error?.message || response?.data?.error?.code || 'Invalid shipping contact details';
                errors.push(new window.ApplePayError('shippingContactInvalid', 'name', errorMessage));
            }
            
            Salla.event.dispatch('payments::apple-pay.authorized.failed', response);
            
            if (typeof SallaApplePay.detail.authorized.onFailed === 'function') {
                SallaApplePay.detail.authorized.onFailed(response);
            }

            // Complete shipping contact selection with invalid contact status
            SallaApplePay.session.completePayment({
                status: ApplePaySession.STATUS_INVALID_SHIPPING_CONTACT,
                errors: errors
            });

            return;
        }

        Salla.event.dispatch('payments::apple-pay.authorized.init', event);
        http.post(SallaApplePay.detail.authorized.url.replace('{id}', SallaApplePay.id), {
            payment_method: 'apple_pay',
            applepay_token: JSON.stringify(event.payment)
        }, ({ data }) => {
            Salla.event.dispatch('payments::apple-pay.authorized.success', data);

            if (typeof SallaApplePay.detail.authorized.onSuccess === 'function') {
                SallaApplePay.detail.authorized.onSuccess(data);
            }

            SallaApplePay.session.completePayment(ApplePaySession.STATUS_SUCCESS);
        }, (error) => {

            let response = error?.response;

            Salla.event.dispatch('payments::apple-pay.authorized.failed', response);

            if (typeof SallaApplePay.detail.authorized.onFailed === 'function') {
                SallaApplePay.detail.authorized.onFailed(response);
            }

            SallaApplePay.session.completePayment({
                status: ApplePaySession.STATUS_FAILURE,
                errors: [new window.ApplePayError("unknown", undefined, response?.data?.error?.message || response?.data?.error?.code || 'Failed to parse authorized response')]
            });
        });
    },

    /**
     * Validate Submit.
     *
     * @param event
     */
    onValidateMerchant: async (event) => {
        try {
            // Dispatch event to initialize Apple Pay merchant validation
            Salla.event.dispatch('payments::apple-pay.validate-merchant.init', event);

            // Post request to validate merchant
            const { data } = await http.post(SallaApplePay.detail.validateMerchant.url.replace('{id}', SallaApplePay.id), {
                validation_url: event.validationURL
            });

            // Dispatch event on successful merchant validation
            Salla.event.dispatch('payments::apple-pay.validate-merchant.success', data);

            // Define a function to handle the completion of merchant validation
            const completeMerchantValidation = (responseData) => {
                SallaApplePay.session.completeMerchantValidation(responseData);
            };

            // Check if onSuccess function is defined in SallaApplePay.detail.validateMerchant
            if (typeof SallaApplePay.detail.validateMerchant.onSuccess === 'function') {
                // Call onSuccess function and handle response
                const response = await SallaApplePay.detail.validateMerchant.onSuccess(data);
                if (response?.redirect) {
                    // Handle redirect if present
                    window.location = response.redirect;
                    return SallaApplePay.abortValidateMerchant(response);
                }
            }
            completeMerchantValidation(data.data);
        } catch (error) {
            // Handle errors
            console.error(error);
            SallaApplePay.abortValidateMerchant(error?.response);
        }
    },

    abortValidateMerchant: (response = null) => {

        SallaApplePay.abortSession();
        Salla.event.dispatch('payments::apple-pay.validate-merchant.failed', response);

        if (typeof SallaApplePay.detail.validateMerchant.onFailed === 'function') {
            SallaApplePay.detail.validateMerchant.onFailed(response);
        }
    },

    /**
     * Select Shipping Contact
     *
     * @param event
     */
    onShippingContactSelected: async (event) => {
        salla.logger.log('🍏 Pay: onShippingContactSelected', event.shippingContact);

        // create address for shipping calculation
        await mutateShippingContact(SallaApplePay, event.shippingContact);
    },

    /**
     * Select Shipping Method
     *
     * @param event
     *
     */
    onShippingMethodSelected: async (event) => {

        let shipping_ids = event.shippingMethod.identifier.split(',');
        let shippingMethod = {
            ship_id: shipping_ids[0],
            private_ship_id: typeof shipping_ids[1] === 'undefined' ? null : shipping_ids[1],
            type: typeof shipping_ids[2] === 'undefined' ? null : shipping_ids[2],
            route_id: typeof shipping_ids[3] === 'undefined' ? null : shipping_ids[3],
        };

        salla.logger.log('🍏 Pay: onShippingMethodSelected', {
            event,
            previous: SallaApplePay.shippingCompany,
            current: shippingMethod,
        });

        if (SallaApplePay.shouldUpdateShippingCompany(shippingMethod)) {
            try {

                await SallaApplePay.selectApplePayShippingMethod(shippingMethod);
    
                await SallaApplePay.recalculateTotal();
    
            } catch (error) {
                salla.logger.warn('🍏 Pay: Failed set the shipping details to api', error);
    
                // todo :: find a better handling for error without abort session
                SallaApplePay.session.completeShippingMethodSelection({
                    newTotal: SallaApplePay.prepareTotal(),
                    newLineItems: SallaApplePay.prepareLineItems(),
                    status: SallaApplePay.session.STATUS_INVALID_SHIPPING_POSTAL_ADDRESS,
                    errors: [
                      new window.ApplePayError('addressUnserviceable')
                    ]
                });

                return;
            }
        }

        salla.logger.log('🍏 Pay: completeShippingMethodSelection', {
            newTotal: SallaApplePay.prepareTotal(),
            newLineItems: SallaApplePay.prepareLineItems(),
        });

        SallaApplePay.session.completeShippingMethodSelection({
            newTotal: SallaApplePay.prepareTotal(),
            newLineItems: SallaApplePay.prepareLineItems(),
        });
    },


    abortSession: () => {
        if (SallaApplePay.session) {
            SallaApplePay.session.abort();
        }
    },

    /* -------------------------------------------------------------------------
     * Payment Request API flow (non-Safari browsers / non-Apple devices).
     * Apple renders the "Scan Code with iPhone" QR sheet. Reuses the same
     * backend endpoints (validate / address / shipping / recalculate / submit)
     * as the native flow; only the sheet-completion model differs
     * (event.updateWith / response.complete instead of session.completeXxx).
     * ---------------------------------------------------------------------- */

    paymentRequest: null,
    paymentResponse: null,

    getCurrency: () => SallaApplePay.detail.currency || 'SAR',

    prAmount: (value) => ({ currency: SallaApplePay.getCurrency(), value: String(value) }),

    prTotal: () => {
        const total = SallaApplePay.prepareTotal();
        return { label: total.label, amount: SallaApplePay.prAmount(total.amount) };
    },

    prDisplayItems: () => SallaApplePay.prepareLineItems().map(item => ({
        label: item.label,
        amount: SallaApplePay.prAmount(item.amount),
    })),

    prShippingOptions: (selectedId = null) => {
        const options = SallaApplePay.mappingShippingMethods(SallaApplePay.shipping_methods || []);
        return options.map((option, index) => ({
            id: option.identifier,
            label: option.label,
            amount: SallaApplePay.prAmount(option.amount),
            selected: selectedId ? option.identifier === selectedId : index === 0,
        }));
    },

    prContactOptions: () => {
        const fields = SallaApplePay.detail.requiredShippingContactFields || [];
        return {
            requestPayerName: fields.includes('name'),
            requestPayerEmail: fields.includes('email'),
            requestPayerPhone: fields.includes('phone'),
            requestShipping: fields.includes('postalAddress'),
            shippingType: 'shipping',
        };
    },

    startPaymentRequestSession: async function () {
        // No merchant identifier in config → Apple Pay isn't set up for this
        // store; bail rather than open a QR sheet that can't be validated.
        const merchantIdentifier = SallaApplePay.getMerchantIdentifier();
        if (!merchantIdentifier) {
            salla.logger.error('🍏 Pay: missing merchant identifier — skipping QR Apple Pay');
            return;
        }

        const version = SallaApplePay.getApplePaySessionVersion();
        const supportedNetworks = [...(SallaApplePay.detail.supportedNetworks || ['masterCard', 'visa'])];
        if (version === 5 && !supportedNetworks.includes('mada')) {
            supportedNetworks.push('mada');
        }

        const methodData = [{
            supportedMethods: APPLE_PAY_METHOD,
            data: {
                version,
                merchantIdentifier,
                merchantCapabilities: ['supports3DS'],
                supportedNetworks,
                countryCode: SallaApplePay.detail.countryCode || 'SA',
            },
        }];

        const requiresShipping = SallaApplePay.isPhysical();

        const details = {
            total: SallaApplePay.prTotal(),
            displayItems: SallaApplePay.prDisplayItems(),
        };
        if (requiresShipping) {
            details.shippingOptions = SallaApplePay.prShippingOptions();
        }

        let request;
        try {
            request = new PaymentRequest(methodData, details, SallaApplePay.prContactOptions());
        } catch (error) {
            salla.logger.error('🍏 Pay: Failed to create PaymentRequest', error);
            SallaApplePay.detail.onError(salla.lang.get('pages.checkout.payment_failed'));
            return;
        }

        SallaApplePay.paymentRequest = request;

        request.onmerchantvalidation = (event) => {
            event.complete(SallaApplePay.prValidateMerchant(event));
        };

        if (requiresShipping) {
            request.onshippingaddresschange = (event) => {
                event.updateWith(SallaApplePay.prShippingAddressChange(request));
            };
            request.onshippingoptionchange = (event) => {
                event.updateWith(SallaApplePay.prShippingOptionChange(request));
            };
        }

        // Showing the sheet is the QR equivalent of ApplePaySession.begin(): it
        // must run inside the user gesture (transient activation). Wrapped so the
        // order-options deferral can drive it — the caller either calls begin()
        // itself (no options → open the QR sheet now) or discards this request
        // and the modal's own Apple Pay button starts a fresh one (options found).
        const beginShow = async () => {
            // The QR sheet is browser chrome (fixed, top layer) that overlays the
            // page. Signal open/closed so hosts embedding Apple Pay (e.g. the
            // mini-checkout modal in an iframe) can hide UI — like their own close
            // button — that would otherwise collide with the sheet.
            Salla.event.dispatch('payments::apple-pay.sheet-opened');
            try {
                const response = await request.show();
                SallaApplePay.paymentResponse = response;
                await SallaApplePay.prPaymentAuthorized(response);
            } catch (error) {
                // AbortError → the shopper dismissed the sheet / QR, or merchant
                // validation rejected. Mirror the native oncancel path so hosts
                // listening for payments::apple-pay.canceled (to reset checkout UI)
                // still get notified on a plain dismissal. The `canceled` guard
                // skips the double-fire when validation already routed through
                // onCancel via validateMerchant.onFailed.
                salla.logger.log('🍏 Pay: PaymentRequest closed', error);
                if (error?.name === 'AbortError' && !SallaApplePay.canceled) {
                    SallaApplePay.onCancel({});
                }
            } finally {
                SallaApplePay.paymentRequest = null;
                SallaApplePay.paymentResponse = null;
                Salla.event.dispatch('payments::apple-pay.sheet-closed');
            }
        };

        // Mirror the native path (startNativeSession): expose a hook between
        // request creation and show(). Returning truthy skips the immediate
        // show() so the order-options modal can open first. Same shim contract
        // as native — the caller only needs `.begin()`.
        let skipBegin;
        if (typeof SallaApplePay.detail.onStartedSession === 'function') {
            skipBegin = SallaApplePay.detail.onStartedSession({ begin: beginShow });
        }
        if (!skipBegin) {
            await beginShow();
        }
    },

    /** Merchant validation — resolves the promise passed to event.complete(). */
    prValidateMerchant: async function (event) {
        Salla.event.dispatch('payments::apple-pay.validate-merchant.init', event);
        try {
            const { data } = await http.post(
                SallaApplePay.detail.validateMerchant.url.replace('{id}', SallaApplePay.id),
                { validation_url: event.validationURL }
            );

            // The BE can return HTTP 200 while Apple actually rejected the session
            // (e.g. statusCode 417 "not a registered merchant in WWDR"), with the
            // real session under data.data. A valid Apple session always carries a
            // merchantSessionIdentifier; its absence means validation failed. Without
            // this the QR sheet just closes silently — notify the shopper and abort.
            if (!data?.data?.merchantSessionIdentifier) {
                salla.logger.error('🍏 Pay: merchant validation failed', data?.statusMessage || data);
                Salla.event.dispatch('payments::apple-pay.validate-merchant.failed', { data });
                SallaApplePay.onCancel({});
                // Dismiss the sheet + paired device immediately. Rejecting
                // event.complete() alone leaves them spinning until Apple's own
                // timeout; abort() forces an instant close. Deferred a tick so it
                // runs after this validation update settles (abort() throws if
                // called while an update is still in flight).
                setTimeout(() => {
                    try { SallaApplePay.paymentRequest?.abort(); } catch (e) { /* already closing */ }
                }, 0);
                const validationError = new Error('Apple Pay merchant validation failed');
                validationError.handled = true;
                throw validationError;
            }

            Salla.event.dispatch('payments::apple-pay.validate-merchant.success', data);

            if (typeof SallaApplePay.detail.validateMerchant.onSuccess === 'function') {
                const response = await SallaApplePay.detail.validateMerchant.onSuccess(data);
                if (response?.redirect) {
                    window.location = response.redirect;
                }
            }

            return data.data;
        } catch (error) {
            // Skip when the invalid-session branch above already notified via onCancel.
            if (!error?.handled) {
                const response = error?.response;
                Salla.event.dispatch('payments::apple-pay.validate-merchant.failed', response);
                if (typeof SallaApplePay.detail.validateMerchant.onFailed === 'function') {
                    SallaApplePay.detail.validateMerchant.onFailed(response);
                }
            }
            // Rethrow so PaymentRequest aborts the sheet.
            throw error;
        }
    },

    /**
     * ISO 3166 alpha-2 code → localized country name. The native path sends the
     * country *name* in `country` (from ApplePayPaymentContact.country) and the
     * ISO code in `country_code`; W3C PaymentAddress only exposes the ISO code,
     * so we derive the name the backend expects. Falls back to the code if
     * Intl.DisplayNames is unavailable or the code is unknown.
     */
    prCountryName: (isoCode) => {
        if (!isoCode) {
            return isoCode;
        }
        try {
            const locale = (salla?.config?.get?.('user.language_code')) || 'en';
            return new Intl.DisplayNames([locale], { type: 'region' }).of(isoCode) || isoCode;
        } catch (e) {
            return isoCode;
        }
    },

    /** Shipping address selected in the sheet → returns a PaymentDetailsUpdate. */
    prShippingAddressChange: async function (request) {
        const address = request.shippingAddress;
        const fallback = {
            total: SallaApplePay.prTotal(),
            displayItems: SallaApplePay.prDisplayItems(),
            shippingOptions: [],
        };

        if (!address) {
            return fallback;
        }

        try {
            const { data } = await http.post(
                SallaApplePay.detail.shippingContactSelected.url.replace('{id}', SallaApplePay.id),
                {
                    country: SallaApplePay.prCountryName(address.country),
                    city: address.city,
                    local: address.dependentLocality || address.region || address.city,
                    description: address.region,
                    street: (address.addressLine || []).join(', ') || address.region,
                    country_code: address.country,
                    postal_code: address.postalCode,
                }
            );

            SallaApplePay.address_id = data.data.address_id;
            SallaApplePay.shipping_methods = data.data.shipping_methods;

            if (!SallaApplePay.shipping_methods?.length) {
                return { ...fallback, error: salla.lang.get('pages.checkout.payment_failed') };
            }

            await SallaApplePay.selectApplePayShippingMethod(SallaApplePay.shipping_methods[0]);
            await SallaApplePay.recalculateTotal();

            return {
                total: SallaApplePay.prTotal(),
                displayItems: SallaApplePay.prDisplayItems(),
                shippingOptions: SallaApplePay.prShippingOptions(),
            };
        } catch (error) {
            salla.logger.warn('🍏 Pay: PR shipping address change failed', error);
            return { ...fallback, error: salla.lang.get('pages.checkout.payment_failed') };
        }
    },

    /** Shipping option selected in the sheet → returns a PaymentDetailsUpdate. */
    prShippingOptionChange: async function (request) {
        const identifier = request.shippingOption;
        if (!identifier) {
            return {
                total: SallaApplePay.prTotal(),
                displayItems: SallaApplePay.prDisplayItems(),
                shippingOptions: SallaApplePay.prShippingOptions(),
            };
        }

        const ids = identifier.split(',');
        const shippingMethod = {
            ship_id: ids[0],
            private_ship_id: typeof ids[1] === 'undefined' ? null : ids[1],
            type: typeof ids[2] === 'undefined' ? null : ids[2],
            route_id: typeof ids[3] === 'undefined' ? null : ids[3],
        };

        try {
            if (SallaApplePay.shouldUpdateShippingCompany(shippingMethod)) {
                await SallaApplePay.selectApplePayShippingMethod(shippingMethod);
                await SallaApplePay.recalculateTotal();
            }
            return {
                total: SallaApplePay.prTotal(),
                displayItems: SallaApplePay.prDisplayItems(),
                shippingOptions: SallaApplePay.prShippingOptions(identifier),
            };
        } catch (error) {
            salla.logger.warn('🍏 Pay: PR shipping option change failed', error);
            return {
                total: SallaApplePay.prTotal(),
                displayItems: SallaApplePay.prDisplayItems(),
                shippingOptions: SallaApplePay.prShippingOptions(identifier),
                error: salla.lang.get('pages.checkout.payment_failed'),
            };
        }
    },

    /** Map the PaymentResponse payer fields to the contact shape the API expects. */
    prContactFromResponse: (response) => {
        const name = (response.payerName || '').trim();
        const spaceIndex = name.indexOf(' ');
        return {
            givenName: spaceIndex > -1 ? name.slice(0, spaceIndex) : name,
            familyName: spaceIndex > -1 ? name.slice(spaceIndex + 1) : '',
            emailAddress: response.payerEmail || null,
            phoneNumber: response.payerPhone || null,
            countryCode: response.shippingAddress?.country || SallaApplePay.detail.countryCode || null,
        };
    },

    /** Authorize + submit the payment, then close the sheet. */
    prPaymentAuthorized: async function (response) {
        // Guest checkout → persist the payer contact before submitting.
        if (SallaApplePay.detail.guestContactSelected) {
            const contact = SallaApplePay.prContactFromResponse(response);

            // Require familyName too, mirroring the native guest guard
            // (utils.js mutateShippingContact). Keeps the payload the backend
            // receives identical to the production native flow — it has only
            // ever been sent a non-empty last_name from Apple Pay guest checkout.
            if (!contact.emailAddress || !contact.givenName || !contact.familyName || !contact.phoneNumber) {
                await response.complete('fail');
                SallaApplePay.detail.onError(salla.lang.get('common.messages.required_fields'));
                return;
            }

            try {
                await http.post(
                    SallaApplePay.detail.guestContactSelected.url.replace('{id}', SallaApplePay.id),
                    {
                        email: contact.emailAddress,
                        first_name: contact.givenName,
                        last_name: contact.familyName,
                        phone_number: contact.phoneNumber,
                        country_code: contact.countryCode,
                    }
                );
            } catch (error) {
                await response.complete('fail');
                SallaApplePay.detail.onError(
                    error?.response?.data?.error?.message || salla.lang.get('pages.checkout.payment_failed')
                );
                return;
            }
        }

        Salla.event.dispatch('payments::apple-pay.authorized.init', response);

        let authorizedData;
        try {
            const { data } = await http.post(
                SallaApplePay.detail.authorized.url.replace('{id}', SallaApplePay.id),
                { payment_method: 'apple_pay', applepay_token: JSON.stringify(response.details) }
            );

            authorizedData = data;
            Salla.event.dispatch('payments::apple-pay.authorized.success', data);
            await response.complete('success');
        } catch (error) {
            const errorResponse = error?.response;
            Salla.event.dispatch('payments::apple-pay.authorized.failed', errorResponse);
            await response.complete('fail');
            if (typeof SallaApplePay.detail.authorized.onFailed === 'function') {
                SallaApplePay.detail.authorized.onFailed(errorResponse);
            }
            return;
        }

        // response.complete() has already run above, and it can only be called
        // once. Run the merchant onSuccess callback OUTSIDE the try/catch so a
        // throw here (e.g. redirect handling) can't fall into the catch and fire
        // a second complete('fail') → InvalidStateError that masks the real error.
        if (typeof SallaApplePay.detail.authorized.onSuccess === 'function') {
            SallaApplePay.detail.authorized.onSuccess(authorizedData);
        }
    },

    shouldUpdateShippingCompany(shippingCompany) {
        return SallaApplePay.shippingCompany?.ship_id != shippingCompany?.ship_id || SallaApplePay.shippingCompany?.private_ship_id != shippingCompany?.private_ship_id
    },

    getApplePaySessionVersion: () => {
        const userAgent = navigator.userAgent || navigator.vendor || window.opera;

        if (userAgent === 'sallapp') {
            return 5;
        }

        // can't handle custom user agent like sallapp
        let detection = DetectOS.init();
        let v = parseFloat(detection.os.version);

        if (detection.os.name === 'Macintosh') {
            if (v < 10.142) {
                return 1;
            }
        } else {
            if (v < 12.11) {
                return 1;
            }
        }

        return 5;
    },

    recalculateTotal: () => {
        salla.logger.log('🍏 Pay: recalculate total');

        return http.get(SallaApplePay.detail.recalculateTotal.url.replace('{id}', SallaApplePay.id), ({ data }) => {
            salla.logger.log('🍏 Pay: recalculate total success', data);
            let cart = data.data.initial_data?.cart || data.data.cart;
            let payments = data.data.initial_data?.payments || data.data.payments;

            salla.logger.log('🍏 Pay: recalculate total success', {
                cart,
                payments
            });

            // BE-canary gate keyed on the live payload (not cached config): the unified BE adds
            // applePay.amount, legacy BE doesn't — so gate and data can never desync.
            if (payments?.gateways?.applePay?.amount != null) {
                // Unified BE: Apple Pay is always charged in the store base currency.
                SallaApplePay.detail.amount = payments.gateways.applePay.amount;
                SallaApplePay.detail.currency = payments.gateways.applePay.currency ?? SallaApplePay.detail.currency;
            } else {
                // Legacy BE .
                SallaApplePay.detail.amount = payments?.gateways?.applePay?.supportedMultiCurrency ? cart.total_in_customer_currency : cart.total;
            }
            SallaApplePay.detail.items = (cart.totals || cart.items).map((item) => {
                return {
                    label: item.title,
                    amount: (item.amount === 'مجاني' || item.amount === 'Free') ? 0 : item.amount.toString().replace('+', ''),
                };
            });

            // lets remove last element (final total)
            SallaApplePay.detail.items.pop();
            SallaApplePay.totals = SallaApplePay.detail.items;

        }, (error) => {
            salla.logger.warn('🍏 Pay: recalculate total failed', error);

            // general error
            return error?.response?.data?.message;
        });
    },


    selectApplePayShippingMethod: (shippingMethod) => {
        salla.logger.log('🍏 Pay: select shipping method ', shippingMethod);
        SallaApplePay.shippingCompany = shippingMethod;

        const payload = {
            address_id: SallaApplePay.address_id,
            company_id: shippingMethod.ship_id,
            private_company_id: shippingMethod.private_ship_id,
            type: shippingMethod.type || undefined,
            route_id: shippingMethod.route_id || undefined,
            payment_method: 'apple_pay'
        };
        return http.post(SallaApplePay.detail.shippingMethodSelected.url.replace('{id}', SallaApplePay.id), payload, ({ data }) => {
            if (typeof SallaApplePay.detail.shippingMethodSelected.onSuccess === 'function') {
                SallaApplePay.detail.shippingMethodSelected.onSuccess(data);
            }

            // we don't have any data in this request, lets resolve the promise
            return true;
        }, (error) => {
            salla.logger.warn('🍏 Pay: Set shipping method failed', error);

            if (typeof SallaApplePay.detail.shippingMethodSelected.onFailed === 'function') {
                SallaApplePay.detail.shippingMethodSelected.onFailed(error);
            }

            // parse 422 errors
            let response = error?.response?.data?.error;

            // address id is not valid
            if (response?.data?.fields?.address_id) {
                return response?.data?.fields?.address_id[0];
            }

            // general error
            return response?.data?.message;
        });
    },
    mappingShippingMethods: methods => methods.map(method => ({
        'label': method.shipping_title,
        'amount': method.enable_free_shipping ? 0 : method.ship_cost,
        'detail': '',
        'identifier': method.ship_id.toString() + (method.private_ship_id ? ',' + method.private_ship_id.toString() : '') + (method.type ? ',' + method.type : '') + (method.route_id ? ',' + method.route_id : '')
    }))
} : {};

// SSR-safe: export and assign to window in browser
if (typeof window !== 'undefined') {
  window.SallaApplePay = SallaApplePay;
}

//applePay doesn't allow iframes
// SSR-safe (init only in the browser). Native (Safari) OR any browser with the
// Payment Request API (non-Safari / QR-code fallback) can start a transaction;
// capability is confirmed per-flow.
if (typeof window !== 'undefined' && (SallaApplePay.canUseNative() || window.PaymentRequest)) {
    SallaApplePay.init();
} else if (typeof document !== 'undefined') {
    // You can hide the Apple Pay button easy with add data-show-if-apple-pay-supported to element like <div data-show-if-apple-pay-supported>
    document.querySelectorAll('data-show-if-apple-pay-supported').forEach(element => element.style.display = 'none');
}

/**
 * Order-options helpers for the Apple Pay quick-buy flow — keeps <salla-quick-buy> to thin AP wiring.
 * Apple Pay resolves options inside the session-started hook (single gesture), so the caller owns
 * the ApplePaySession and drives it via callbacks.
 */
/** Get-or-create the singleton order-options modal on <body>. */
function ensureOrderOptionsModal() {
    let modal = document.querySelector('salla-order-options-modal');
    if (!modal) {
        modal = document.createElement('salla-order-options-modal');
        document.body.appendChild(modal);
    }
    return modal;
}
/** Sync PDP-option validity (an `await` would consume the Apple Pay gesture). Skips hidden/disabled inputs. */
function reportProductOptionsValiditySync(productId) {
    const optionsElement = document.querySelector(`salla-product-options[product-id="${productId}"]`);
    if (!optionsElement)
        return true;
    const requiredInputs = optionsElement.querySelectorAll('[required]');
    let pass = true;
    requiredInputs.forEach((input) => {
        if (input.disabled || input.closest('.hidden'))
            return;
        if ('reportValidity' in input && !input.reportValidity())
            pass = false;
    });
    return pass;
}
/** Merge collected order-options into the quick-purchase payload (FormData or plain object). */
function appendOrderOptionsToPayload(data, orderOptions) {
    if (!orderOptions.length)
        return;
    if (data && typeof data.append === 'function') {
        orderOptions.forEach((entry, i) => {
            data.append(`order_options[${i}][id]`, String(entry.id));
            data.append(`order_options[${i}][value]`, String(entry.value));
        });
        return;
    }
    if (data && typeof data === 'object') {
        data.order_options = orderOptions;
    }
}
/**
 * Fetch order options and, if any, collect them via the modal (apple-pay mode). Callbacks drive the
 * caller's pre-created session: `beginPendingSession` (no options), `discardPendingSession` (options
 * found — the modal's AP button starts a fresh one), `onSubmit` (submitted).
 */
async function resolveApplePayOrderOptions(opts) {
    let resp;
    try {
        resp = await salla.api.withoutNotifier(() => salla.product.api.getOrderOptions([{ id: opts.productId, quantity: opts.quantity }]));
    }
    catch (error) {
        salla?.logger?.warn?.('order-options: fetch failed', error);
        opts.beginPendingSession();
        return;
    }
    const items = resp?.data?.order_options || [];
    if (!items.length) {
        opts.beginPendingSession(); // begin() doesn't need a fresh gesture
        return;
    }
    opts.discardPendingSession(); // drop the unused session; the modal builds a fresh one
    const basePrice = Number(opts.amount) > 0
        ? Number(opts.amount)
        : Number(resp?.data?.products?.[0]?.price?.amount) || 0;
    const modal = ensureOrderOptionsModal();
    try {
        await modal.open({
            orderOptions: items,
            basePrice,
            paymentMode: 'apple-pay',
            onSubmit: opts.onSubmit,
        });
    }
    catch {
        // dismissed — no live session
    }
}

const sallaQuickBuyCss = "/*!twlt*/.s-quick-buy-button .s-button-text{display:flex}apple-pay-button{--apple-pay-button-width:100%;--apple-pay-button-height:40px;--apple-pay-button-border-radius:.75rem;--apple-pay-button-box-sizing:content-box}.s-add-product-button-with-sticky-bar salla-quick-buy .s-quick-buy-button .s-button-text span{display:none}@media (min-width: 768px){.s-add-product-button-with-sticky-bar salla-quick-buy .s-quick-buy-button .s-button-text span{display:block}}.s-quick-buy-button svg{margin-right:0.375rem;height:1rem;width:1rem}.s-quick-buy-button svg:where([dir=\"rtl\"],[dir=\"rtl\"] *){margin-right:0px;margin-left:0.375rem}.s-quick-buy-apple-pay{display:block;width:100%}@media (min-width: 640px){.s-quick-buy-apple-pay{margin-top:0.625rem}}.s-quick-buy-apple-pay .apple-pay-btn-wrapper .apple-pay-btn{width:auto !important;border-radius:var(--s-radius, 0.25rem) !important}";

const SallaQuickBuy = class {
    constructor(hostRef) {
        registerInstance(this, hostRef);
        this.validationFailed = createEvent(this, "validationFailed");
        this.requireLogin = createEvent(this, "requireLogin");
        /**
         * Button type.
         *
         * @type {string}
         * @default buy
         **/
        this.type = 'buy';
        /**
         * Product type.
         *
         * @type {string}
         **/
        this.productType = 'product';
        /**
         * Product options, if is empty will get the data from the document.querySelector('salla-product-options[product-id="X"]')
         *
         * @type {object}
         * @default {}
         */
        this.options = {};
        /** Modal selections, merged into the quick-purchase payload. */
        this.collectedOrderOptions = [];
        /** Flips true after the first onStartedSession so the second dispatch begins. */
        this.optionsResolved = false;
        /** PDP price + selected order-option prices (from the modal). */
        this.applePayAmount = 0;
        /** Session from the initial gesture; begun later when there are no order options. */
        this.pendingApplePaySession = null;
        this.quickBuy = salla.lang.get('pages.products.buy_now');
        /** Apple Pay onStartedSession: first call defers begin() to run the OO check; second (resolved) begins. */
        this.handleApplePaySessionStarted = (session) => {
            // Order options disabled → let Apple Pay begin normally, as if the feature didn't exist.
            if (!salla.config.get('store.settings.order_options.mandatory', false))
                return false;
            if (this.optionsResolved)
                return false;
            this.optionsResolved = true;
            this.pendingApplePaySession = session;
            resolveApplePayOrderOptions({
                productId: this.productId,
                amount: Number(this.amount),
                quantity: this.getSelectedQuantity(),
                beginPendingSession: () => {
                    this.pendingApplePaySession?.begin();
                    this.pendingApplePaySession = null;
                },
                discardPendingSession: () => { this.pendingApplePaySession = null; },
                onSubmit: (selections, total) => {
                    this.collectedOrderOptions = selections;
                    this.applePayAmount = total;
                    this.settlePayment();
                },
            });
            return true;
        };
        salla.lang.onLoaded(() => {
            this.quickBuy = salla.lang.get('pages.products.buy_now');
        });
    }
    quickBuyHandler() {
        if (salla.config.isGuest() && !this.isGuestCheckout()) {
            this.requireLogin.emit({ productId: this.productId });
            salla.api.auth.requireLoginThen('salla-quick-buy::user.logged-in', () => this.quickBuyHandler());
            return;
        }
        // Sync validate — AP needs the gesture preserved for new ApplePaySession().
        if (!this.validatePdpOptionsSync())
            return;
        this.optionsResolved = false;
        this.collectedOrderOptions = [];
        this.applePayAmount = 0;
        this.settlePayment();
    }
    /** Sync PDP-option validity (preserves the AP gesture); emits + notifies on failure. */
    validatePdpOptionsSync() {
        if (reportProductOptionsValiditySync(this.productId))
            return true;
        this.validationFailed.emit({ productId: this.productId });
        salla.error(salla.lang.get('common.messages.required_fields'));
        return false;
    }
    /** Read the live PDP quantity from the form so order-options match the real cart line. */
    getSelectedQuantity() {
        try {
            const data = this.host.getElementSallaData?.();
            const qty = Number(data instanceof FormData ? data.get('quantity') : data?.quantity);
            return Number.isFinite(qty) && qty > 0 ? qty : 1;
        }
        catch {
            return 1;
        }
    }
    async settlePayment() {
        //use this way to get quantity too
        let data = this.host.getElementSallaData();
        appendOrderOptionsToPayload(data, this.collectedOrderOptions);
        // mini-checkout takes the product in the request body (quick-purchase used the URL).
        // set() overwrites any `id` the surrounding product form already carries — append() would duplicate it.
        if ('set' in data) {
            data.set('id', this.productId);
            data.set('source', 'buy_now');
        }
        else {
            data.id = this.productId;
            data.source = 'buy_now';
        }
        // if the store doesn't have Apple Pay , just create a cart and then redirect to check out page
        if (!this.isApplePayActive) {
            return salla.api.request('checkout/mini', data, 'post')
                .catch(err => this.legacyQuickPurchaseFallback(err, data))
                .then(resp => {
                // mini-checkout answers {to, url}; legacy quick-purchase answered {redirect}
                const redirect = resp.data?.url || resp.data?.redirect;
                if (redirect) {
                    window.location.href = redirect;
                }
                else if (resp.data?.to === 'login') {
                    salla.event.dispatch('login::open');
                }
                return resp;
            });
        }
        data.is_applepay = true;
        if ('append' in data) {
            data.append('is_applepay', true);
        }
        // noinspection TypeScriptValidateJSTypes
        salla.event.dispatch('payments::apple-pay.start-transaction', {
            // Prefer the modal's collected total (PDP price + selected OO additional_prices).
            // Falls back to PDP live amount when no OO modal ran.
            amount: this.applePayAmount > 0 ? this.applePayAmount : this.amount,
            currency: this.currency || salla.config.get('store.settings.buy_now.currency') || 'SAR', // SAR
            requiredShippingContactFields: this.getRequiredShippingContactFields(),
            shippingMethods: this.isRequireShipping ? [] : undefined,
            supportedNetworks: (Array.isArray(this.supportedNetworks) && this.supportedNetworks.length)
                ? this.supportedNetworks : salla.config.get('store.settings.buy_now.supportedNetworks'),
            supportedCountries: (Array.isArray(this.supportedCountries) && this.supportedCountries.length)
                ? this.supportedCountries : salla.config.get('store.settings.buy_now.supportedCountries'),
            countryCode: salla.config.get('store.store_country') || 'SA',
            merchantIdentifier: applePayMerchantId(),
            onStartedSession: this.handleApplePaySessionStarted,
            validateMerchant: {
                url: this.validateHost ? `${this.validateHost}/checkout/applepay/validate` : salla.url.get('checkout/applepay/validate'),
                onSuccess: (response) => {
                    if (this.applePayOnly && !this.productId) { // the cart is not passes
                        if (!this.cartId) {
                            salla.logger.warn('🍏 Pay: trying to create applePay transaction without cartId/ProductId !');
                            return Promise.resolve(response);
                        }
                        window.SallaApplePay.id = this.cartId;
                        salla.log('🍏 Pay: create checkout success: with id #' + this.cartId);
                        return Promise.resolve(response);
                    }
                    return salla.api.request('checkout/mini', typeof data == 'object' ? data : undefined, 'post', {})
                        .catch(err => this.legacyQuickPurchaseFallback(err, typeof data == 'object' ? data : undefined))
                        .then(response => {
                        // the cart id keeps the Apple Pay session going; mini-checkout exposes it
                        // in the checkout url path (`/checkout/{cart}`), same encoding quick-purchase returned
                        const cartId = response?.data?.id
                            || response?.data?.url?.split('/checkout/')[1]?.split(/[/?#]/)[0];
                        if (cartId) {
                            window.SallaApplePay.id = cartId;
                            salla.log('🍏 Pay: create checkout success: with id #' + window.SallaApplePay.id);
                            return response;
                        }
                        // no cart id: fall back to the checkout page if any redirect url was returned
                        const redirect = response?.data?.url || response?.data?.redirect?.url || response?.data?.redirect;
                        if (redirect) {
                            salla.log('🍏 Pay: create checkout success: redirect exits, go to checkout page');
                            window.location.href = redirect;
                            return response;
                        }
                        // the cart is not ready to complete apply pay session
                        salla.logger.warn('🍏 Pay: create checkout success: No id, or redirect');
                        return response;
                    });
                }
            },
            authorized: {
                // submit checkout route
                url: salla.url.get('checkout/{id}/payments/submit'),
                onFailed: (response) => {
                    window.SallaApplePay.onCancel({}, response?.data?.error?.message || response?.data?.error?.code || salla.lang.get('pages.checkout.payment_failed'));
                },
                onSuccess: (response) => {
                    window.location.href = response.redirect.url;
                    salla.log('🍏 Pay: authorized Success:: redirect to thank you page, order placed');
                }
            },
            shippingMethodSelected: this.isRequireShipping ? {
                url: salla.url.get('checkout/{id}/shipping/details'),
            } : undefined,
            shippingContactSelected: this.isRequireShipping ? {
                url: salla.url.get('checkout/{id}/address/add'),
            } : undefined,
            guestContactSelected: this.isGuestCheckout() ? {
                url: salla.url.get('checkout/{id}/customer'),
            } : undefined,
            onCouponCodeChanged: {
                url: salla.url.get('checkout/{id}/coupons')
            },
            recalculateTotal: {
                url: salla.url.get('checkout/{id}/payments/recalculate?payment_method=apple_pay')
            },
            onError: function (message) {
                salla.log(message);
                salla.notify.error(message);
            }
        });
    }
    legacyQuickPurchaseFallback(err, data) {
        if (err?.response?.data?.error?.code !== 'token_not_provided') {
            throw err;
        }
        salla.logger.warn('quick-buy: falling back to quick-purchase because of token_not_provided');
        return salla.api.request('checkout/quick-purchase/' + this.productId, data, 'post');
    }
    isGuestCheckout() {
        return salla.config.isGuest() && salla.config.get('store.features').includes('guest-checkout') && this.isPhysicalProduct();
    }
    getRequiredShippingContactFields() {
        let fields = [];
        if (this.isRequireShipping) {
            fields.push('postalAddress');
        }
        if (this.isGuestCheckout()) {
            fields.push('email', 'phone', 'name');
        }
        return fields;
    }
    /** Set Apple Pay amount + currency from a price payload, always keeping the pair in one currency. */
    applyBaseCurrencyPrice(data) {
        const base = data?.base_currency_price;
        // Unified BE base pair (regular products): charge in base currency.
        if (base?.amount != null) {
            this.amount = base.amount;
            if (base?.currency) {
                this.currency = base.currency;
            }
            // Display-only payload (e.g. donation { id, price }): pair amount with its display currency.
        }
        else if (data?.price != null) {
            this.amount = data.price;
            this.currency = salla.config.get('user.currency_code') || this.currency || 'SAR';
        }
    }
    componentWillLoad() {
        console.log('🍏 Pay: Quick Buy Component Loaded');
        const canMakePayments = typeof window !== 'undefined' && !!window.ApplePaySession?.canMakePayments?.();
        const storeHasApplePay = salla?.config?.get?.('store.settings.payments')?.includes?.('apple_pay') ?? true;
        const isSallaGateway = salla?.config?.get?.('store.settings.is_salla_gateway', false) ?? true;
        this.isApplePayActive = canMakePayments && storeHasApplePay && isSallaGateway;
        const runInit = async () => {
            if (!this.productId && salla?.config?.get && salla.url?.is_page) {
                this.productId = salla.config.get('page.id');
            }
            if (!this.applePayOnly && !this.productId) {
                salla?.logger?.warn?.('🍏 Pay: Failed load the quick buy, the product id is missing');
                return;
            }
            if ((!this.amount || !this.isRequireShipping) && this.productId && salla?.product?.getDetails) {
                await salla.product.getDetails(this.productId, []).then((response) => {
                    this.applyBaseCurrencyPrice(response?.data);
                    this.isRequireShipping = response?.data?.is_require_shipping || false;
                }).catch((error) => {
                    salla?.logger?.warn?.('🍏 Pay: Failed load the quick buy, get the product details failed: ', error);
                });
            }
            if (this.type === 'donate' && salla?.event?.on) {
                salla.event.on('product-options::donation-changed', (data) => {
                    if (String(data.id) !== String(this.productId))
                        return;
                    this.applyBaseCurrencyPrice(data);
                });
            }
            else if (salla?.url?.is_page?.('product.single') && salla?.product?.event?.onPriceUpdated) {
                salla.product.event.onPriceUpdated(response => { this.applyBaseCurrencyPrice(response?.data); });
            }
            const storeAllowsApplePay = (salla?.config?.get?.('store.settings.payments')?.includes?.('apple_pay') ?? storeHasApplePay)
                && (salla?.config?.get?.('store.settings.is_salla_gateway', false) ?? isSallaGateway);
            // Preload Apple's JS SDK so the rendered <apple-pay-button> upgrades on
            // every flow (native Safari + QR). Fire-and-forget: the element upgrades
            // retroactively once the script defines it.
            if (storeAllowsApplePay) {
                ensureApplePaySdk();
            }
            // Cross-browser capability: native (Safari) OR the Payment Request API
            // (non-Safari browsers / non-Apple devices via the QR-code fallback). The
            // helper loads Apple's JS SDK and awaits it before probing, so this is a
            // stable answer on first load (no race against the async script fetch).
            this.isApplePayActive = storeAllowsApplePay && await canCompleteApplePay(this.currency);
        };
        return new Promise((resolve) => {
            if (typeof salla?.onReady === 'function') {
                salla.onReady(() => runInit().then(() => resolve(true)));
            }
            else {
                runInit().then(() => resolve(true));
            }
        });
    }
    render() {
        return h(Host, { key: 'fd28f7292f396779cbe6ae4d5986ab187be38c48' }, this.quickBuyButton());
    }
    quickBuyButton() {
        return h("apple-pay-button", { locale: salla?.config?.get?.('user.language_code') || 'ar', onClick: () => this.quickBuyHandler(), "data-quick-purchase": "applepay", class: "s-quick-buy-apple-pay", "data-is-applepay": "1", buttonstyle: "black", type: this.type });
    }
    // function to check if product is physical
    isPhysicalProduct() {
        return this.productType === 'product' || this.productType === 'group_products' || this.productType === 'food';
    }
    get host() { return getElement(this); }
};
SallaQuickBuy.style = sallaQuickBuyCss;

export { SallaAddProductButton as salla_add_product_button, SallaBoughtTogether as salla_bought_together, SallaProductAvailability as salla_product_availability, SallaProductOptions as salla_product_options, SallaQuickBuy as salla_quick_buy };
